_render_cache = {}

def get_lucide_pixmap(name, color="#ffffff", size=20):
    key = (name, color, size)
    if key in _render_cache:
        return _render_cache[key]

    raw_svg = LUCIDE_SVGS.get(name)
    if not raw_svg:
        return QPixmap()

    svg_content = raw_svg.format(color=color)
    renderer = QSvgRenderer(QByteArray(svg_content.encode("utf-8")))

    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    renderer.render(painter, QRectF(0, 0, size, size))
    painter.end()

    _render_cache[key] = pixmap
    return pixmap

def get_lucide_icon(name, color="#ffffff", size=20):
    pixmap = get_lucide_pixmap(name, color, size)
    return QIcon(pixmap)

def draw_lucide_icon(painter, rect, name, color="#ffffff"):
    """Vẽ trực tiếp Lucide Vector Icon lên QPainter tại ô rect chỉ định."""
    size = min(int(rect.width()), int(rect.height()))
    pixmap = get_lucide_pixmap(name, color, size)
    if not pixmap.isNull():
        x = rect.x() + (rect.width() - size) / 2
        y = rect.y() + (rect.height() - size) / 2
        painter.drawPixmap(int(x), int(y), pixmap)
